export function dialoguesByGrade(grade: number): Dialogue[] {
  return DIALOGUES.filter((d) => d.grade === grade);
}

export function dialogueById(id: string): Dialogue | undefined {
  return DIALOGUES.find((d) => d.id === id);
}
